// node ab3.mjs <engine> <op> <doc> <iters> <reps> >> out.jsonl
// Same per-process method as carve-bench#106 ab.mjs, three variants rotated each repetition.
import { execFileSync } from 'node:child_process'
const W = 'WORKSPACE'
const P = 'FIRST_RUN_WORKSPACE'
const PHPF = ['-n', '-d', 'extension=ctype', '-d', 'extension=mbstring', '-d', 'zend_extension=opcache', '-d', 'opcache.enable_cli=1', '-d', 'opcache.jit=tracing', '-d', 'opcache.jit_buffer_size=128M', '-d', 'memory_limit=4G']
const [engine, op, doc, iters, reps] = process.argv.slice(2)
const paths = {
  js: { rel: `${P}/carve-js-rel/dist/index.js`, main0340: `${P}/carve-js/dist/index.js`, now: `${W}/carve-js/dist/index.js` },
  php: { rel: `${P}/carve-php-rel/src`, main0340: `${P}/carve-php/src`, now: `${W}/carve-php/src` },
  rs: { rel: `${P}/_ab/rs-rel`, main0340: `${P}/_ab/rs-main`, now: `${W}/_ab/rs-main-now` },
}[engine]
const labels = Object.keys(paths)
const load = () => Number(execFileSync('cat', ['/proc/loadavg'], { encoding: 'utf8' }).split(' ')[0])
for (let r = 0; r < Number(reps); r++) {
  for (let i = 0; i < labels.length; i++) {
    const label = labels[(i + r) % labels.length]
    const p = paths[label]
    const [c, args] = engine === 'js' ? ['node', [`${W}/_ab/js.mjs`, p, op, doc, iters]]
      : engine === 'php' ? ['php', [...PHPF, `${W}/_ab/php.php`, p, op, doc, iters]]
      : [p, [op, doc, iters]]
    let ms = null
    try { ms = JSON.parse(execFileSync(c, args, { encoding: 'utf8', maxBuffer: 1 << 26, timeout: 900000 }).trim().split('\n').pop()).ms } catch { ms = null }
    console.log(JSON.stringify({ engine, op, doc: doc.split('/').pop(), variant: label, rep: r, ms, load: load() }))
  }
}
